secureScript.script:
import groovy.json.JsonSlurper
def folder = new File("/backups/sites")
if (folder.exists() && folder.isDirectory()) {
    def files = folder.listFiles({ file -> file.name.endsWith(".json") } as FileFilter)
    if (files) {
        def slurper = new JsonSlurper()
        def sites = []
        files.each { file ->
            try {
                def metadata = slurper.parse(file)
                if (metadata.status == "enabled") {
                    sites.add(file.name.minus(".json"))
                }
            } catch (e) {}
        }
        return sites ? sites.sort() : ["No active sites found"]
    }
}
return ["No active sites found"]
